#include "stdafx.h"#include "H_Class.h"static SBlockCreate DOCHANNEL( "DOCHANNEL", SH_DOCHANNEL::Create );SH_DOCHANNEL::SH_DOCHANNEL(): pMaster( NULL ){}#include <HPARM_INIT.h> #include "ParmVarInfo.h"LIST_PARM(SH_DOCHANNEL,W_DOCHANNEL,50)void SH_DOCHANNEL::InitParm(){#include "Blocks/DOCHANNEL.h" s_defFlag = SVarInfo::efParam;#include "Blocks/DOCHANNEL_P.h"  qsort ( VarInfo, kVarInfo, sizeof ( SVarInfo ), CompVarInfo );}static LPCSTR s_ConPoint = "SO";LPCSTR SH_DOCHANNEL::SetDestIO( KBmBase *dest, LPCSTR pszField ){  if( this==dest )    return s_ConPoint;  eVarType type = evtHZ;  BYTE *pV = NULL;  bool b = dest->GetVar( s_ConPoint, &pV, &type );  ASS( b );  ASS( type==evtBool );  pMaster = (BYTE*)pV;  return s_ConPoint;}struct W_DOCHANNEL_IMPL : W_DOCHANNEL{  void StepT( SStepCalcParams &dt, double &prevONOFFPULSE, double &timerTo0 );};void SH_DOCHANNEL::StepT( SStepCalcParams &dt ){  if( pMaster )  {    W->SO = *pMaster;    return;  }  __super::StepT( dt );  W_DOCHANNEL_IMPL *impl = (W_DOCHANNEL_IMPL*)W;  impl->StepT( dt, prevONOFFPULSE, timerTo0 );}void SH_DOCHANNEL::StepAfterRestoreState(){  switch( W->DOTYPE.V )  {  case W_DOCHANNEL::_DOTYPE::OnPulse:    prevONOFFPULSE = W->ONPULSE;    break;  case W_DOCHANNEL::_DOTYPE::OffPulse:    prevONOFFPULSE = W->OFFPULSE;    break;  }  timerTo0 = 0;}void W_DOCHANNEL_IMPL::StepT( SStepCalcParams &dt, double &prevONOFFPULSE, double &timerTo0 ){  switch( DOTYPE.V )  {  case _DOTYPE::OnPulse:    if( timerTo0 > 0 )    {      SO = true;      timerTo0 -= dt;    }    else    {      SO = false;      if( prevONOFFPULSE != ONPULSE )        timerTo0 = ONPULSE;      else        timerTo0 = 0;      prevONOFFPULSE = ONPULSE;    }    break;  case _DOTYPE::OffPulse:    if( timerTo0 > 0 )    {      SO = false;      timerTo0 -= dt;    }    else    {      SO = true;      if( prevONOFFPULSE != OFFPULSE )        timerTo0 = OFFPULSE;      else        timerTo0 = 0;      prevONOFFPULSE = OFFPULSE;    }    break;  case _DOTYPE::STATUS:    break;  default:    ASSD(0);  }}